public class Solution {
    public double Average(int[] salary) {
        long sum = 0;
        int min = int.MaxValue;
        int max = int.MinValue;
        foreach (int s in salary) {
            sum += s;
            if (s < min) min = s;
            if (s > max) max = s;
        }
        sum -= min;
        sum -= max;
        return (double)sum / (salary.Length - 2);
    }
}
