public class Solution {
    public string AbbreviateProduct(int left, int right) {
        long twos = 0, fives = 0;
        for (int i = left; i <= right; i++) {
            int x = i;
            while (x % 2 == 0) { twos++; x /= 2; }
            while (x % 5 == 0) { fives++; x /= 5; }
        }
        long C = Math.Min(twos, fives);
        long remove2 = C, remove5 = C;
        long MOD = 10000000000L;
        long suffix = 1;
        bool big = false;
        double prefix = 1.0;
        for (int i = left; i <= right; i++) {
            long x = i;
            while (x % 2 == 0 && remove2 > 0) { x /= 2; remove2--; }
            while (x % 5 == 0 && remove5 > 0) { x /= 5; remove5--; }
            suffix *= x;
            if (suffix >= MOD) {
                big = true;
                suffix %= MOD;
            }
            prefix *= x;
            while (prefix >= 100000.0) prefix /= 10.0;
        }
        if (!big) {
            return suffix.ToString() + "e" + C.ToString();
        }
        long first5 = (long)prefix;
        long last5 = suffix % 100000;
        return first5.ToString() + "..." + last5.ToString("D5") + "e" + C.ToString();
    }
}
