using System;
using System.Collections.Generic;

public class Solution {
    public IList<string> AmbiguousCoordinates(string s) {
        var result = new List<string>();
        string digits = s.Substring(1, s.Length - 2);
        for (int i = 1; i < digits.Length; i++) {
            var left = Generate(digits.Substring(0, i));
            var right = Generate(digits.Substring(i));
            foreach (var l in left) {
                foreach (var r in right) {
                    result.Add("(" + l + ", " + r + ")");
                }
            }
        }
        return result;
    }

    private List<string> Generate(string str) {
        var res = new List<string>();
        int n = str.Length;
        if (n == 0) return res;
        // integer form
        if (n == 1 || str[0] != '0') {
            res.Add(str);
        }
        // decimal forms
        for (int i = 1; i < n; i++) {
            string intPart = str.Substring(0, i);
            string fracPart = str.Substring(i);
            if (intPart.Length > 1 && intPart[0] == '0') continue;
            if (fracPart[fracPart.Length - 1] == '0') continue;
            res.Add(intPart + "." + fracPart);
        }
        return res;
    }
}
