Classic reverse union-find approach: remove all hit bricks, build DSU with a virtual roof node, then add bricks back in reverse order and count how many become newly attached to the roof.

```csharp
public class Solution {
    private int[] parent;
    private int[] size;

    private int Find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void Union(int a, int b) {
        int ra = Find(a), rb = Find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    public int[] HitBricks(int[][] grid, int[][] hits) {
        int m = grid.Length, n = grid[0].Length;
        int roof = m * n;
        parent = new int[m * n + 1];
        size = new int[m * n + 1];
        for (int i = 0; i <= m * n; i++) { parent[i] = i; size[i] = 1; }

        int[][] g = new int[m][];
        for (int i = 0; i < m; i++) {
            g[i] = new int[n];
            for (int j = 0; j < n; j++) g[i][j] = grid[i][j];
        }
        foreach (var h in hits) {
            if (g[h[0]][h[1]] == 1) g[h[0]][h[1]] = 2; // mark as removed brick
        }

        int[] dr = { 1, -1, 0, 0 };
        int[] dc = { 0, 0, 1, -1 };

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (g[i][j] != 1) continue;
                int id = i * n + j;
                if (i == 0) Union(id, roof);
                if (i + 1 < m && g[i + 1][j] == 1) Union(id, (i + 1) * n + j);
                if (j + 1 < n && g[i][j + 1] == 1) Union(id, i * n + j + 1);
            }
        }

        int[] res = new int[hits.Length];
        for (int k = hits.Length - 1; k >= 0; k--) {
            int r = hits[k][0], c = hits[k][1];
            if (g[r][c] != 2) { res[k] = 0; continue; }
            int before = size[Find(roof)];
            int id = r * n + c;
            g[r][c] = 1;
            if (r == 0) Union(id, roof);
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                if (g[nr][nc] == 1) Union(id, nr * n + nc);
            }
            int after = size[Find(roof)];
            res[k] = after > before ? after - before - 1 : 0;
        }
        return res;
    }
}
```

