public class Solution {
    public int NumFactoredBinaryTrees(int[] arr) {
        const long MOD = 1000000007L;
        Array.Sort(arr);
        int n = arr.Length;
        var dp = new Dictionary<int, long>();
        long total = 0;
        for (int i = 0; i < n; i++) {
            long count = 1;
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int other = arr[i] / arr[j];
                    if (dp.TryGetValue(other, out long val)) {
                        count = (count + dp[arr[j]] * val) % MOD;
                    }
                }
            }
            dp[arr[i]] = count;
            total = (total + count) % MOD;
        }
        return (int)total;
    }
}
