Simulate with a stack: push n, then for each next number apply *, /, +, - in rotation; multiply/divide operate on the stack top, add pushes positive, subtract pushes negative. Sum at the end.

```csharp
using System;
using System.Collections.Generic;

public class Solution {
    public int Clumsy(int n) {
        Stack<long> stack = new Stack<long>();
        stack.Push(n);
        int op = 0;
        for (int i = n - 1; i >= 1; i--) {
            if (op == 0) {
                long top = stack.Pop();
                stack.Push(top * i);
            } else if (op == 1) {
                long top = stack.Pop();
                stack.Push(top / i);
            } else if (op == 2) {
                stack.Push(i);
            } else {
                stack.Push(-i);
            }
            op = (op + 1) % 4;
        }
        long sum = 0;
        foreach (long v in stack) sum += v;
        return (int)sum;
    }
}
```

