public class MKAverage {
    private int m, k;
    private const int N = 100000;
    private long[] cntTree;
    private long[] sumTree;
    private Queue<int> q;
    private long total;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        cntTree = new long[N + 1];
        sumTree = new long[N + 1];
        q = new Queue<int>();
        total = 0;
    }

    private void Update(int idx, long dc, long ds) {
        for (int i = idx; i <= N; i += i & (-i)) {
            cntTree[i] += dc;
            sumTree[i] += ds;
        }
    }

    private long SumSmallest(int count) {
        if (count <= 0) return 0;
        int pos = 0;
        long remaining = count;
        long s = 0;
        for (int i = 17; i >= 0; i--) {
            int next = pos + (1 << i);
            if (next <= N && cntTree[next] < remaining) {
                pos = next;
                remaining -= cntTree[next];
                s += sumTree[next];
            }
        }
        s += remaining * (pos + 1);
        return s;
    }

    public void AddElement(int num) {
        q.Enqueue(num);
        Update(num, 1, num);
        total += num;
        if (q.Count > m) {
            int old = q.Dequeue();
            Update(old, -1, -old);
            total -= old;
        }
    }

    public int CalculateMKAverage() {
        if (q.Count < m) return -1;
        long low = SumSmallest(k);
        long upTo = SumSmallest(m - k);
        long mid = upTo - low;
        return (int)(mid / (m - 2 * k));
    }
}

