Classic DP: for each stone index i, keep the set of jump sizes k that can land on it. From stone i with jump k, try k-1, k, k+1 to reach later stones via a position→index map. Since jump sizes at stone i are bounded by about i+1, use a boolean table dp[i][k] of size n×(n+1).

```csharp
using System;
using System.Collections.Generic;

public class Solution {
    public bool CanCross(int[] stones) {
        int n = stones.Length;
        if (n == 1) return true;
        if (stones[1] != 1) return false;
        var pos = new Dictionary<long, int>();
        for (int i = 0; i < n; i++) pos[stones[i]] = i;
        // dp[i][k] = frog can reach stone i with last jump k
        bool[][] dp = new bool[n][];
        for (int i = 0; i < n; i++) dp[i] = new bool[n + 2];
        dp[1][1] = true;
        for (int i = 1; i < n; i++) {
            for (int k = 1; k <= n; k++) {
                if (!dp[i][k]) continue;
                if (i == n - 1) return true;
                for (int d = -1; d <= 1; d++) {
                    int nk = k + d;
                    if (nk <= 0 || nk > n) continue;
                    long target = (long)stones[i] + nk;
                    if (pos.TryGetValue(target, out int j) && j > i) {
                        dp[j][nk] = true;
                    }
                }
            }
        }
        for (int k = 1; k <= n; k++) if (dp[n - 1][k]) return true;
        return false;
    }
}
```

