public class Solution {
    public int MaxPoints(int[][] points) {
        int n = points.Length;
        if (n <= 2) return n;
        int best = 1;
        for (int i = 0; i < n; i++) {
            var dict = new Dictionary<(int, int), int>();
            int localMax = 0;
            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                int g = Gcd(Math.Abs(dx), Math.Abs(dy));
                dx /= g;
                dy /= g;
                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }
                var key = (dx, dy);
                int cnt;
                dict.TryGetValue(key, out cnt);
                cnt++;
                dict[key] = cnt;
                if (cnt > localMax) localMax = cnt;
            }
            if (localMax + 1 > best) best = localMax + 1;
        }
        return best;
    }

    private int Gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}
