public class Solution {
    public int MaxScore(int[] nums) {
        int m = nums.Length;
        int full = (1 << m) - 1;
        int[,] g = new int[m, m];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < m; j++)
                g[i, j] = Gcd(nums[i], nums[j]);
        int[] dp = new int[1 << m];
        for (int mask = 0; mask < full; mask++) {
            int cnt = PopCount(mask);
            if ((cnt & 1) == 1) continue;
            int op = cnt / 2 + 1;
            for (int i = 0; i < m; i++) {
                if ((mask >> i & 1) == 1) continue;
                for (int j = i + 1; j < m; j++) {
                    if ((mask >> j & 1) == 1) continue;
                    int nm = mask | (1 << i) | (1 << j);
                    int val = dp[mask] + op * g[i, j];
                    if (val > dp[nm]) dp[nm] = val;
                }
            }
        }
        return dp[full];
    }

    private int PopCount(int x) {
        int c = 0;
        while (x != 0) { x &= x - 1; c++; }
        return c;
    }

    private int Gcd(int a, int b) {
        while (b != 0) { int t = a % b; a = b; b = t; }
        return a;
    }
}
