public class Solution {
    public int CountVowelSubstrings(string word) {
        int n = word.Length;
        int count = 0;
        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (int j = i; j < n; j++) {
                char c = word[j];
                int bit;
                switch (c) {
                    case 'a': bit = 1; break;
                    case 'e': bit = 2; break;
                    case 'i': bit = 4; break;
                    case 'o': bit = 8; break;
                    case 'u': bit = 16; break;
                    default: bit = -1; break;
                }
                if (bit < 0) break;
                mask |= bit;
                if (mask == 31) count++;
            }
        }
        return count;
    }
}
