Classic base-3 bitmask DP: each slot has state 0,1,2 (count of numbers placed). Iterate over masks; the number of placed items equals the sum of digits; place nums[count] into any slot with capacity remaining.

```csharp
public class Solution {
    public int MaximumANDSum(int[] nums, int numSlots) {
        int n = nums.Length;
        int total = 1;
        for (int i = 0; i < numSlots; i++) total *= 3;
        int[] dp = new int[total];
        int[] pow3 = new int[numSlots + 1];
        pow3[0] = 1;
        for (int i = 1; i <= numSlots; i++) pow3[i] = pow3[i - 1] * 3;
        int best = 0;
        for (int mask = 0; mask < total; mask++) {
            int cnt = 0;
            int m = mask;
            for (int i = 0; i < numSlots; i++) {
                cnt += m % 3;
                m /= 3;
            }
            if (cnt >= n) {
                if (cnt == n) best = System.Math.Max(best, dp[mask]);
                continue;
            }
            int val = nums[cnt];
            m = mask;
            for (int i = 0; i < numSlots; i++) {
                int d = m % 3;
                m /= 3;
                if (d < 2) {
                    int nm = mask + pow3[i];
                    int cand = dp[mask] + (val & (i + 1));
                    if (cand > dp[nm]) dp[nm] = cand;
                }
            }
        }
        return best;
    }
}
```

