- maxFreq == 1 (remove any one element), or
- freq[maxFreq] * maxFreq == i (one element with count 1 can be removed), or
- (maxFreq-1) * (freq[maxFreq-1] + 1) == i (one element with maxFreq count, remove one occurrence).

```csharp
public class Solution {
    public int MaxEqualFreq(int[] nums) {
        int n = nums.Length;
        int[] count = new int[100001];
        int[] freq = new int[100002];
        int maxFreq = 0;
        int result = 0;
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            if (count[x] > 0) freq[count[x]]--;
            count[x]++;
            freq[count[x]]++;
            if (count[x] > maxFreq) maxFreq = count[x];
            int len = i + 1;
            if (maxFreq == 1) {
                result = len;
            } else if ((long)freq[maxFreq] * maxFreq == len - 1) {
                result = len;
            } else if ((long)(maxFreq - 1) * (freq[maxFreq - 1] + 1) == len && freq[maxFreq] == 1) {
                result = len;
            }
        }
        return result;
    }
}
