    public string Evaluate(string s, IList<IList<string>> knowledge) {
        var dict = new Dictionary<string, string>();
        foreach (var kv in knowledge) {
            dict[kv[0]] = kv[1];
        }
        var sb = new StringBuilder();
        int i = 0;
        int n = s.Length;
        while (i < n) {
            char c = s[i];
            if (c == '(') {
                int j = i + 1;
                while (j < n && s[j] != ')') j++;
                string key = s.Substring(i + 1, j - i - 1);
                if (dict.TryGetValue(key, out string val)) {
                    sb.Append(val);
                } else {
                    sb.Append('?');
                }
                i = j + 1;
            } else {
                sb.Append(c);
                i++;
            }
        }
        return sb.ToString();
    }
}
