Classic sliding window: for a window [l, r] of fruits (positions p[l]..p[r]), the minimal steps needed is `min(|startPos - p[l]| + (p[r]-p[l]), |startPos - p[r]| + (p[r]-p[l]))`. Slide r forward, shrink l while cost exceeds k.

```csharp
public class Solution {
    public int MaxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.Length;
        int l = 0;
        long sum = 0;
        int best = 0;
        for (int r = 0; r < n; r++) {
            sum += fruits[r][1];
            while (l <= r && Cost(fruits[l][0], fruits[r][0], startPos) > k) {
                sum -= fruits[l][1];
                l++;
            }
            if (l <= r && sum > best) best = (int)sum;
        }
        return best;
    }

    private long Cost(int left, int right, int start) {
        long width = right - left;
        long a = Math.Abs((long)start - left) + width;
        long b = Math.Abs((long)start - right) + width;
        return Math.Min(a, b);
    }
}
```

