    public IList<int> FindKDistantIndices(int[] nums, int key, int k) {
        var result = new List<int>();
        int n = nums.Length;
        int next = 0;
        for (int j = 0; j < n; j++) {
            if (nums[j] == key) {
                int start = Math.Max(next, j - k);
                int end = Math.Min(n - 1, j + k);
                for (int i = start; i <= end; i++) {
                    result.Add(i);
