public class Solution {
    public long MaxRunTime(int n, int[] batteries) {
        long total = 0;
        foreach (int b in batteries) total += b;
        long lo = 0, hi = total / n;
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2;
            long sum = 0;
            foreach (int b in batteries) {
                sum += b < mid ? b : mid;
            }
            if (sum >= mid * n) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }
}
