```csharp
public class Solution {
    public int LargestMagicSquare(int[][] grid) {
        int m = grid.Length, n = grid[0].Length;
        long[,] rowPre = new long[m, n + 1];
        long[,] colPre = new long[m + 1, n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rowPre[i, j + 1] = rowPre[i, j] + grid[i][j];
                colPre[i + 1, j] = colPre[i, j] + grid[i][j];
            }
        }
        int maxK = Math.Min(m, n);
        for (int k = maxK; k >= 2; k--) {
            for (int r = 0; r + k <= m; r++) {
                for (int c = 0; c + k <= n; c++) {
                    if (Check(grid, rowPre, colPre, r, c, k)) return k;
                }
            }
        }
        return 1;
    }

    private bool Check(int[][] grid, long[,] rowPre, long[,] colPre, int r, int c, int k) {
        long target = rowPre[r, c + k] - rowPre[r, c];
        for (int i = r; i < r + k; i++) {
            if (rowPre[i, c + k] - rowPre[i, c] != target) return false;
        }
        for (int j = c; j < c + k; j++) {
            if (colPre[r + k, j] - colPre[r, j] != target) return false;
        }
        long d1 = 0, d2 = 0;
        for (int t = 0; t < k; t++) {
            d1 += grid[r + t][c + t];
            d2 += grid[r + t][c + k - 1 - t];
        }
        return d1 == target && d2 == target;
    }
}
