        int full = 1 << n;
        int[] prev = new int[full];
        for (int s = 0; s < full; s++) prev[s] = -1;
        prev[0] = 0;
        for (int i = 0; i < m; i++) {
            int[] cur = new int[full];
            for (int s = 0; s < full; s++) cur[s] = -1;
            for (int s = 0; s < full; s++) {
                if ((s & valid[i]) != s) continue;
                if ((s & (s << 1)) != 0) continue;
                int cnt = CountBits(s);
                for (int p = 0; p < full; p++) {
                    if (prev[p] < 0) continue;
                    if ((s & (p << 1)) != 0) continue;
                    if ((s & (p >> 1)) != 0) continue;
                    int val = prev[p] + cnt;
                    if (val > cur[s]) cur[s] = val;
                }
            }
            prev = cur;
        }
        int best = 0;
        for (int s = 0; s < full; s++) {
            if (prev[s] > best) best = prev[s];
        }
        return best;
    }

    private int CountBits(int x) {
        int c = 0;
        while (x != 0) {
            x &= x - 1;
            c++;
        }
        return c;
    }
}
