Classic approach: build union-find over non-initial nodes, then for each component count how many distinct initial nodes touch it. Components touched by exactly one initial node are saved if that node is removed; pick the initial node saving the most nodes (smallest index on ties).

```csharp
public class Solution {
    private int[] parent;
    private int[] size;

    private int Find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void Union(int a, int b) {
        int ra = Find(a), rb = Find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    public int MinMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.Length;
        bool[] isInitial = new bool[n];
        foreach (int x in initial) isInitial[x] = true;

        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }

        for (int i = 0; i < n; i++) {
            if (isInitial[i]) continue;
            for (int j = i + 1; j < n; j++) {
                if (isInitial[j]) continue;
                if (graph[i][j] == 1) Union(i, j);
            }
        }

        // For each component root: which initial node touches it (-1 none, -2 multiple)
        int[] touchedBy = new int[n];
        for (int i = 0; i < n; i++) touchedBy[i] = -1;

        foreach (int u in initial) {
            var seen = new HashSet<int>();
            for (int v = 0; v < n; v++) {
                if (isInitial[v] || graph[u][v] == 0) continue;
                int r = Find(v);
                if (!seen.Add(r)) continue;
                if (touchedBy[r] == -1) touchedBy[r] = u;
                else if (touchedBy[r] != u) touchedBy[r] = -2;
            }
        }

        int[] saved = new int[n];
        for (int r = 0; r < n; r++) {
            if (isInitial[r] || Find(r) != r) continue;
            if (touchedBy[r] >= 0) saved[touchedBy[r]] += size[r];
        }

        int best = -1, bestSaved = -1;
        foreach (int u in initial) {
            if (saved[u] > bestSaved || (saved[u] == bestSaved && u < best)) {
                bestSaved = saved[u];
                best = u;
            }
        }
        return best;
    }
}
