DP over time: dp[t][v] = min cost to reach v at exactly time t. Iterate t from 1 to maxTime, relax all edges. Complexity O(maxTime * edges) = 1e6.

```csharp
public class Solution {
    public int MinCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.Length;
        const int INF = int.MaxValue / 2;
        int[][] dp = new int[maxTime + 1][];
        for (int t = 0; t <= maxTime; t++) {
            dp[t] = new int[n];
            for (int i = 0; i < n; i++) dp[t][i] = INF;
        }
        dp[0][0] = passingFees[0];
        for (int t = 1; t <= maxTime; t++) {
            foreach (var e in edges) {
                int u = e[0], v = e[1], w = e[2];
                if (w > t) continue;
                int pt = t - w;
                if (dp[pt][u] < INF) {
                    int c = dp[pt][u] + passingFees[v];
                    if (c < dp[t][v]) dp[t][v] = c;
                }
                if (dp[pt][v] < INF) {
                    int c = dp[pt][v] + passingFees[u];
                    if (c < dp[t][u]) dp[t][u] = c;
                }
            }
        }
        int ans = INF;
        for (int t = 0; t <= maxTime; t++) {
            if (dp[t][n - 1] < ans) ans = dp[t][n - 1];
        }
        return ans >= INF ? -1 : ans;
    }
}
