Bitmask DP over mentors assigned: dp[mask] = max score assigning first popcount(mask) students to mentors in mask.

```csharp
public class Solution {
    public int MaxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.Length;
        int n = students[0].Length;
        int[,] score = new int[m, m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int s = 0;
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) s++;
                }
                score[i, j] = s;
            }
        }
        int full = 1 << m;
        int[] dp = new int[full];
        for (int i = 0; i < full; i++) dp[i] = -1;
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] < 0) continue;
            int student = 0;
            for (int b = mask; b > 0; b >>= 1) student += b & 1;
            if (student >= m) continue;
            for (int j = 0; j < m; j++) {
                if ((mask & (1 << j)) != 0) continue;
                int nm = mask | (1 << j);
                int val = dp[mask] + score[student, j];
                if (val > dp[nm]) dp[nm] = val;
            }
        }
        return dp[full - 1];
    }
}
