Classic approach: number of ways = product over nodes of C(left+right, left), computed recursively; subtract 1 for the original ordering. Use Pascal's triangle for binomials mod 1e9+7.

```csharp
using System;
using System.Collections.Generic;

public class Solution {
    private const long MOD = 1000000007L;
    private long[][] comb;

    public int NumOfWays(int[] nums) {
        int n = nums.Length;
        comb = new long[n + 1][];
        for (int i = 0; i <= n; i++) {
            comb[i] = new long[i + 1];
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
            }
        }
        List<int> list = new List<int>(nums);
        long result = Count(list);
        return (int)((result - 1 + MOD) % MOD);
    }

    private long Count(List<int> arr) {
        if (arr.Count <= 2) return 1;
        int root = arr[0];
        List<int> left = new List<int>();
        List<int> right = new List<int>();
        for (int i = 1; i < arr.Count; i++) {
            if (arr[i] < root) left.Add(arr[i]);
            else right.Add(arr[i]);
        }
        long ways = comb[arr.Count - 1][left.Count];
        ways = ways * Count(left) % MOD;
        ways = ways * Count(right) % MOD;
        return ways;
    }
}
```

