Binary search on days; for a given day, count bouquets greedily by scanning adjacent bloomed flowers. Note `m * k` can overflow int, so use long.

```csharp
public class Solution {
    public int MinDays(int[] bloomDay, int m, int k) {
        long need = (long)m * k;
        if (need > bloomDay.Length) return -1;
        int lo = int.MaxValue, hi = 0;
        foreach (int d in bloomDay) {
            if (d < lo) lo = d;
            if (d > hi) hi = d;
        }
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (CanMake(bloomDay, m, k, mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private bool CanMake(int[] bloomDay, int m, int k, int day) {
        int bouquets = 0, run = 0;
        foreach (int d in bloomDay) {
            if (d <= day) {
                run++;
                if (run == k) {
                    bouquets++;
                    run = 0;
                    if (bouquets >= m) return true;
                }
            } else {
                run = 0;
            }
        }
        return bouquets >= m;
    }
}
```

