Classic: choose n non-adjacent slices in a circular array to maximize sum. Solve linear version twice (excluding first or last element).

```csharp
public class Solution {
    public int MaxSizeSlices(int[] slices) {
        int m = slices.Length;
        int n = m / 3;
        if (m == 1) return slices[0];
        int[] a = new int[m - 1];
        int[] b = new int[m - 1];
        for (int i = 0; i < m - 1; i++) {
            a[i] = slices[i];
            b[i] = slices[i + 1];
        }
        return Math.Max(Solve(a, n), Solve(b, n));
    }

    private int Solve(int[] arr, int n) {
        int len = arr.Length;
        const int NEG = int.MinValue / 2;
        // dp[i][j]: max sum using first i elements, picking j non-adjacent
        int[,] dp = new int[len + 1, n + 1];
        for (int i = 0; i <= len; i++)
            for (int j = 0; j <= n; j++)
                dp[i, j] = NEG;
        for (int i = 0; i <= len; i++) dp[i, 0] = 0;
        for (int i = 1; i <= len; i++) {
            for (int j = 1; j <= n; j++) {
                int skip = dp[i - 1, j];
                int take = (i >= 2 ? dp[i - 2, j - 1] : (j - 1 == 0 ? 0 : NEG));
                if (take != NEG) take += arr[i - 1];
                dp[i, j] = Math.Max(skip, take);
            }
        }
        return dp[len, n];
    }
}
```

