        int maxNeg = 0;
        foreach (char c in s) {
            if (c == '[') {
                balance++;
            } else {
                balance--;
                if (-balance > maxNeg) {
                    maxNeg = -balance;
                }
            }
        }
        return (maxNeg + 1) / 2;
    }
}
