Classic bitmask DP: for each subset, track (sessions, remaining time in current session), minimized lexicographically.

```csharp
public class Solution {
    public int MinSessions(int[] tasks, int sessionTime) {
        int n = tasks.Length;
        int full = 1 << n;
        // dp[mask] = (sessions, timeUsedInLastSession) encoded as sessions * 100 + used
        int[] dp = new int[full];
        for (int i = 0; i < full; i++) dp[i] = int.MaxValue;
        dp[0] = 0; // 0 sessions, 0 used -> effectively treat as needing new session
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] == int.MaxValue) continue;
            int sessions = dp[mask] / 100;
            int used = dp[mask] % 100;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int nmask = mask | (1 << i);
                int ns, nu;
                if (sessions > 0 && used + tasks[i] <= sessionTime) {
                    ns = sessions;
                    nu = used + tasks[i];
                } else {
                    ns = sessions + 1;
                    nu = tasks[i];
                }
                int val = ns * 100 + nu;
                if (val < dp[nmask]) dp[nmask] = val;
            }
        }
        return dp[full - 1] / 100;
    }
}
```

