Use a monotonic stack over the array traversed twice (indices modulo n), popping smaller elements and assigning their next greater value.

```csharp
public class Solution {
    public int[] NextGreaterElements(int[] nums) {
        int n = nums.Length;
        int[] res = new int[n];
        for (int i = 0; i < n; i++) res[i] = -1;
        var stack = new Stack<int>();
        for (int i = 0; i < 2 * n; i++) {
            int idx = i % n;
            while (stack.Count > 0 && nums[stack.Peek()] < nums[idx]) {
                res[stack.Pop()] = nums[idx];
            }
            if (i < n) stack.Push(idx);
        }
        return res;
    }
}
```

