Classic approach: compute the number of extra '(' and ')' to remove, then DFS deciding for each parenthesis whether to keep or remove it, tracking balance and pruning. Use a HashSet to dedupe.

```csharp
using System;
using System.Collections.Generic;
using System.Text;

public class Solution {
    private HashSet<string> result;
    private string str;

    public IList<string> RemoveInvalidParentheses(string s) {
        result = new HashSet<string>();
        str = s;
        int left = 0, right = 0;
        foreach (char c in s) {
            if (c == '(') left++;
            else if (c == ')') {
                if (left > 0) left--;
                else right++;
            }
        }
        Dfs(0, 0, left, right, new StringBuilder());
        return new List<string>(result);
    }

    private void Dfs(int idx, int balance, int leftRem, int rightRem, StringBuilder sb) {
        if (balance < 0) return;
        if (idx == str.Length) {
            if (balance == 0 && leftRem == 0 && rightRem == 0) {
                result.Add(sb.ToString());
            }
            return;
        }
        char c = str[idx];
        int len = sb.Length;
        if (c == '(') {
            if (leftRem > 0) {
                Dfs(idx + 1, balance, leftRem - 1, rightRem, sb);
            }
            sb.Append(c);
            Dfs(idx + 1, balance + 1, leftRem, rightRem, sb);
            sb.Length = len;
        } else if (c == ')') {
            if (rightRem > 0) {
                Dfs(idx + 1, balance, leftRem, rightRem - 1, sb);
            }
            if (balance > 0) {
                sb.Append(c);
                Dfs(idx + 1, balance - 1, leftRem, rightRem, sb);
                sb.Length = len;
            }
        } else {
            sb.Append(c);
            Dfs(idx + 1, balance, leftRem, rightRem, sb);
            sb.Length = len;
        }
    }
}
