Classic 3D DP: dp[len][i][j] = whether s1[i..i+len) can be scrambled into s2[j..j+len).

```csharp
public class Solution {
    public bool IsScramble(string s1, string s2) {
        int n = s1.Length;
        if (n != s2.Length) return false;
        if (s1 == s2) return true;
        bool[,,] dp = new bool[n + 1, n, n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                dp[1, i, j] = s1[i] == s2[j];
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len <= n; i++) {
                for (int j = 0; j + len <= n; j++) {
                    bool ok = false;
                    for (int k = 1; k < len && !ok; k++) {
                        if (dp[k, i, j] && dp[len - k, i + k, j + k]) ok = true;
                        else if (dp[k, i, j + len - k] && dp[len - k, i + k, j]) ok = true;
                    }
                    dp[len, i, j] = ok;
                }
            }
        }
        return dp[n, 0, 0];
    }
}
