using System;
using System.Collections.Generic;

public class Solution {
    public double[] MedianSlidingWindow(int[] nums, int k) {
        int n = nums.Length;
        double[] res = new double[n - k + 1];
        var cmp = Comparer<(int val, int idx)>.Create((a, b) => {
            if (a.val != b.val) return a.val.CompareTo(b.val);
            return a.idx.CompareTo(b.idx);
        });
        var low = new SortedSet<(int val, int idx)>(cmp);
        var high = new SortedSet<(int val, int idx)>(cmp);

        void Rebalance() {
            while (low.Count > high.Count + 1) {
                var m = low.Max;
                low.Remove(m);
                high.Add(m);
            }
            while (high.Count > low.Count) {
                var m = high.Min;
                high.Remove(m);
                low.Add(m);
            }
        }

        void Insert(int i) {
            var item = (nums[i], i);
            if (low.Count == 0 || nums[i] <= low.Max.val) low.Add(item);
            else high.Add(item);
        }

        void RemoveItem(int i) {
            var item = (nums[i], i);
            if (!low.Remove(item)) high.Remove(item);
        }

        for (int i = 0; i < k; i++) {
            Insert(i);
        }
        Rebalance();

        for (int i = k; i <= n; i++) {
            if (k % 2 == 1) {
                res[i - k] = low.Max.val;
            } else {
                res[i - k] = ((long)low.Max.val + (long)high.Min.val) / 2.0;
            }
            if (i == n) break;
            RemoveItem(i - k);
            Insert(i);
            Rebalance();
        }
        return res;
    }
}
