Standard backtracking with sorting descending and bucket pruning, or bitmask DP. I'll use bitmask DP over subsets: dp[mask] = sum of used elements mod target (or -1 if invalid), where we only add element i if current remainder + nums[i] <= target.

```csharp
public class Solution {
    public bool CanPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        foreach (int x in nums) total += x;
        if (total % k != 0) return false;
        int target = total / k;
        foreach (int x in nums) if (x > target) return false;
        int n = nums.Length;
        int full = 1 << n;
        int[] dp = new int[full];
        for (int i = 0; i < full; i++) dp[i] = -1;
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] < 0) continue;
            int cur = dp[mask];
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int next = mask | (1 << i);
                if (dp[next] >= 0) continue;
                if (cur + nums[i] <= target) {
                    dp[next] = (cur + nums[i]) % target;
                }
            }
        }
        return dp[full - 1] == 0;
    }
}
```

