Binary search on the answer: for a candidate maximum sum, greedily count how many subarrays are needed; if at most k, the candidate is feasible.

```csharp
public class Solution {
    public int SplitArray(int[] nums, int k) {
        long lo = 0, hi = 0;
        foreach (int x in nums) {
            hi += x;
            if (x > lo) lo = x;
        }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (Feasible(nums, k, mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }

    private bool Feasible(int[] nums, int k, long limit) {
        int count = 1;
        long cur = 0;
        foreach (int x in nums) {
            if (cur + x > limit) {
                count++;
                cur = x;
                if (count > k) return false;
            } else {
                cur += x;
            }
        }
        return true;
    }
}
```

