Classic bitmask DP over subsets of target characters: dp[mask] = min stickers to cover characters in mask. For each reachable mask, for each sticker, greedily apply sticker letters to uncovered target positions.

```csharp
public class Solution {
    public int MinStickers(string[] stickers, string target) {
        int m = target.Length;
        int full = (1 << m) - 1;
        int n = stickers.Length;
        int[][] cnt = new int[n][];
        for (int i = 0; i < n; i++) {
            cnt[i] = new int[26];
            foreach (char c in stickers[i]) cnt[i][c - 'a']++;
        }
        int[] dp = new int[1 << m];
        for (int i = 0; i <= full; i++) dp[i] = int.MaxValue;
        dp[0] = 0;
        int[] tmp = new int[26];
        for (int mask = 0; mask <= full; mask++) {
            if (dp[mask] == int.MaxValue) continue;
            for (int i = 0; i < n; i++) {
                for (int k = 0; k < 26; k++) tmp[k] = cnt[i][k];
                int nmask = mask;
                for (int j = 0; j < m; j++) {
                    if ((mask & (1 << j)) != 0) continue;
                    int c = target[j] - 'a';
                    if (tmp[c] > 0) {
                        tmp[c]--;
                        nmask |= (1 << j);
                    }
                }
                if (nmask != mask && dp[mask] + 1 < dp[nmask]) {
                    dp[nmask] = dp[mask] + 1;
                }
            }
        }
        return dp[full] == int.MaxValue ? -1 : dp[full];
    }
}
```

