Classic union-find approach: split each cell into 4 triangles (top=0, right=1, bottom=2, left=3), union within the cell based on the character, then union with neighboring cells' adjacent triangles, and count the number of distinct components.

```csharp
public class Solution {
    private int[] parent;

    private int Find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private void Union(int a, int b) {
        int ra = Find(a), rb = Find(b);
        if (ra != rb) parent[ra] = rb;
    }

    public int RegionsBySlashes(string[] grid) {
        int n = grid.Length;
        parent = new int[n * n * 4];
        for (int i = 0; i < parent.Length; i++) parent[i] = i;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int baseIdx = (r * n + c) * 4;
                char ch = grid[r][c];
                if (ch == '/') {
                    Union(baseIdx + 0, baseIdx + 3);
                    Union(baseIdx + 1, baseIdx + 2);
                } else if (ch == '\\') {
                    Union(baseIdx + 0, baseIdx + 1);
                    Union(baseIdx + 2, baseIdx + 3);
                } else {
                    Union(baseIdx + 0, baseIdx + 1);
                    Union(baseIdx + 1, baseIdx + 2);
                    Union(baseIdx + 2, baseIdx + 3);
                }
                // connect with right neighbor
                if (c + 1 < n) {
                    int rightBase = (r * n + c + 1) * 4;
                    Union(baseIdx + 1, rightBase + 3);
                }
                // connect with bottom neighbor
                if (r + 1 < n) {
                    int downBase = ((r + 1) * n + c) * 4;
                    Union(baseIdx + 2, downBase + 0);
                }
            }
        }

        int count = 0;
        for (int i = 0; i < parent.Length; i++) {
            if (Find(i) == i) count++;
        }
        return count;
    }
}
