Reverse trie approach: insert reversed words, keep a buffer of recent characters (bounded by max word length), and on each query walk backwards through the buffer along the trie.

```csharp
public class StreamChecker {
    private class Node {
        public Node[] Children = new Node[26];
        public bool IsEnd;
    }

    private Node root;
    private char[] buffer;
    private int maxLen;
    private int pos;
    private int count;

    public StreamChecker(string[] words) {
        root = new Node();
        maxLen = 0;
        foreach (var w in words) {
            if (w.Length > maxLen) maxLen = w.Length;
            Node cur = root;
            for (int i = w.Length - 1; i >= 0; i--) {
                int c = w[i] - 'a';
                if (cur.Children[c] == null) cur.Children[c] = new Node();
                cur = cur.Children[c];
            }
            cur.IsEnd = true;
        }
        buffer = new char[maxLen];
        pos = 0;
        count = 0;
    }

    public bool Query(char letter) {
        buffer[pos] = letter;
        pos = (pos + 1) % maxLen;
        if (count < maxLen) count++;
        Node cur = root;
        for (int k = 0; k < count; k++) {
            int idx = ((pos - 1 - k) % maxLen + maxLen) % maxLen;
            int c = buffer[idx] - 'a';
            cur = cur.Children[c];
            if (cur == null) return false;
            if (cur.IsEnd) return true;
        }
        return false;
    }
}

