        var adj = new Dictionary<int, List<int>>(n * 2);
        foreach (var p in adjacentPairs) {
            if (!adj.TryGetValue(p[0], out var l0)) { l0 = new List<int>(2); adj[p[0]] = l0; }
            l0.Add(p[1]);
            if (!adj.TryGetValue(p[1], out var l1)) { l1 = new List<int>(2); adj[p[1]] = l1; }
            l1.Add(p[0]);
        }
        int start = 0;
        foreach (var kv in adj) {
            if (kv.Value.Count == 1) { start = kv.Key; break; }
        }
        int[] res = new int[n];
        res[0] = start;
        int prev = int.MinValue;
        bool hasPrev = false;
        int cur = start;
        for (int i = 1; i < n; i++) {
            var list = adj[cur];
            int next;
            if (!hasPrev || list[0] != prev) next = list[0];
            else next = list[1];
            res[i] = next;
            prev = cur;
            hasPrev = true;
            cur = next;
        }
        return res;
    }
