```csharp
public class Solution {
    private int[,,] memoMin;
    private int[,,] memoMax;

    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memoMin = new int[n + 1, n + 1, n + 1];
        memoMax = new int[n + 1, n + 1, n + 1];
        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= n; j++)
                for (int k = 0; k <= n; k++) {
                    memoMin[i, j, k] = -1;
                    memoMax[i, j, k] = -1;
                }
        Solve(n, firstPlayer, secondPlayer);
        return new int[] { memoMin[n, firstPlayer, secondPlayer], memoMax[n, firstPlayer, secondPlayer] };
    }

    private void Solve(int n, int f, int s) {
        if (memoMin[n, f, s] != -1) return;
        if (f + s == n + 1) {
            memoMin[n, f, s] = 1;
            memoMax[n, f, s] = 1;
            return;
        }
        // normalize so that f is on the left half (f < n+1-s)
        if (f + s > n + 1) {
            int nf = n + 1 - s;
            int ns = n + 1 - f;
            Solve(n, nf, ns);
            memoMin[n, f, s] = memoMin[n, nf, ns];
            memoMax[n, f, s] = memoMax[n, nf, ns];
            return;
        }
        int best = int.MaxValue, worst = int.MinValue;
        int half = (n + 1) / 2;
        // players left of f: f-1 ; they can win or lose. i = number of winners among them who remain left of f in new arrangement
        // players between f and s: s-f-1
        if (s <= half) {
            // both in first half; s's mirror is in the right part
            for (int i = 0; i < f; i++) { // i survivors placed before f
                for (int j = 0; j < s - f; j++) { // j survivors between f and s
                    int nf = i + 1;
                    int ns = i + 1 + j + 1;
                    Solve(half, nf, ns);
                    best = System.Math.Min(best, memoMin[half, nf, ns] + 1);
                    worst = System.Math.Max(worst, memoMax[half, nf, ns] + 1);
                }
            }
        } else {
            // f in left half, s in right half (past middle), f+s < n+1
            int sMirror = n + 1 - s; // position of s's opponent, sMirror > f
            // players between f and sMirror: sMirror - f - 1; these choose freely
            // players between sMirror and s: (s - sMirror - 1); half of them survive automatically in pairs
            int mid = (s - sMirror - 1) / 2;
            for (int i = 0; i < f; i++) {
                for (int j = 0; j < sMirror - f; j++) {
                    int nf = i + 1;
                    int ns = i + 1 + j + mid + 1;
                    Solve(half, nf, ns);
                    best = System.Math.Min(best, memoMin[half, nf, ns] + 1);
                    worst = System.Math.Max(worst, memoMax[half, nf, ns] + 1);
                }
            }
        }
        memoMin[n, f, s] = best;
        memoMax[n, f, s] = worst;
    }
}
