public class Solution {
    public int SumOddLengthSubarrays(int[] arr) {
        int n = arr.Length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            int count = ((i + 1) * (n - i) + 1) / 2;
            total += arr[i] * count;
        }
        return total;
    }
}
