using System;
using System.Collections.Generic;

public class Solution {
    public IList<IList<string>> SuggestedProducts(string[] products, string searchWord) {
        Array.Sort(products, StringComparer.Ordinal);
        var result = new List<IList<string>>();
        int start = 0;
        int n = products.Length;
        for (int i = 0; i < searchWord.Length; i++) {
            char c = searchWord[i];
            // advance start to first product that has matching prefix at position i
            while (start < n && (products[start].Length <= i || products[start][i] < c)) {
                start++;
            }
            var list = new List<string>();
            for (int j = start; j < n && j < start + 3; j++) {
                string p = products[j];
                if (p.Length > i && p[i] == c && string.CompareOrdinal(p, 0, searchWord, 0, i + 1) == 0) {
                    list.Add(p);
                } else {
                    break;
                }
            }
            // if start no longer matches prefix, subsequent prefixes won't match either
            if (list.Count == 0) {
                start = n;
            }
            result.Add(list);
        }
        return result;
    }
}
