```csharp
using System;
using System.Collections.Generic;

public class Solution {
    public int[] GetCoprimes(int[] nums, int[][] edges) {
        int n = nums.Length;
        var adj = new List<int>[n];
        for (int i = 0; i < n; i++) adj[i] = new List<int>();
        foreach (var e in edges) {
            adj[e[0]].Add(e[1]);
            adj[e[1]].Add(e[0]);
        }
        bool[,] coprime = new bool[51, 51];
        for (int a = 1; a <= 50; a++)
            for (int b = 1; b <= 50; b++)
                coprime[a, b] = Gcd(a, b) == 1;

        int[] ans = new int[n];
        var stacks = new List<(int node, int depth)>[51];
        for (int v = 1; v <= 50; v++) stacks[v] = new List<(int, int)>();

        int[] parent = new int[n];
        int[] depth = new int[n];
        int[] idx = new int[n];
        var stack = new Stack<int>();
        parent[0] = -1;
        depth[0] = 0;
        stack.Push(0);
        // Process node 0 on entry
        Enter(0, nums, coprime, stacks, ans, depth);
        while (stack.Count > 0) {
            int u = stack.Peek();
            if (idx[u] < adj[u].Count) {
                int v = adj[u][idx[u]++];
                if (v == parent[u]) continue;
                parent[v] = u;
                depth[v] = depth[u] + 1;
                Enter(v, nums, coprime, stacks, ans, depth);
                stack.Push(v);
            } else {
                stack.Pop();
                var st = stacks[nums[u]];
                st.RemoveAt(st.Count - 1);
            }
        }
        return ans;
    }

    private void Enter(int u, int[] nums, bool[,] coprime, List<(int node, int depth)>[] stacks, int[] ans, int[] depth) {
        int best = -1, bestDepth = -1;
        int val = nums[u];
        for (int v = 1; v <= 50; v++) {
            if (!coprime[val, v]) continue;
            var st = stacks[v];
            if (st.Count > 0) {
                var top = st[st.Count - 1];
                if (top.depth > bestDepth) {
                    bestDepth = top.depth;
                    best = top.node;
                }
            }
        }
        ans[u] = best;
        stacks[val].Add((u, depth[u]));
    }

    private int Gcd(int a, int b) {
        while (b != 0) { int t = a % b; a = b; b = t; }
        return a;
    }
}
