public class Solution {
    public int[] KWeakestRows(int[][] mat, int k) {
        int m = mat.Length;
        int[] counts = new int[m];
        int[] idx = new int[m];
        for (int i = 0; i < m; i++) {
            int lo = 0, hi = mat[i].Length;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (mat[i][mid] == 1) lo = mid + 1;
                else hi = mid;
            }
            counts[i] = lo;
            idx[i] = i;
        }
        Array.Sort(idx, (a, b) => {
            if (counts[a] != counts[b]) return counts[a].CompareTo(counts[b]);
            return a.CompareTo(b);
        });
        int[] result = new int[k];
        Array.Copy(idx, result, k);
        return result;
    }
}
