Standard spiral simulation: move east, south, west, north with step lengths 1,1,2,2,3,3,... and record cells within bounds until all rows*cols cells are visited.

```csharp
public class Solution {
    public int[][] SpiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int total = rows * cols;
        int[][] result = new int[total][];
        int count = 0;
        int r = rStart, c = cStart;
        result[count++] = new int[] { r, c };
        int[] dr = { 0, 1, 0, -1 };
        int[] dc = { 1, 0, -1, 0 };
        int dir = 0;
        int steps = 1;
        while (count < total) {
            for (int k = 0; k < 2 && count < total; k++) {
                for (int s = 0; s < steps && count < total; s++) {
                    r += dr[dir];
                    c += dc[dir];
                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        result[count++] = new int[] { r, c };
                    }
                }
                dir = (dir + 1) % 4;
            }
            steps++;
        }
        return result;
    }
}
