Greedy approach: at each step, append the letter with more remaining count unless the last two characters are already that letter, in which case append the other.

```csharp
using System.Text;

public class Solution {
    public string StrWithout3a3b(int a, int b) {
        var sb = new StringBuilder();
        int lastA = 0, lastB = 0;
        while (a > 0 || b > 0) {
            bool writeA;
            if (lastA == 2) writeA = false;
            else if (lastB == 2) writeA = true;
            else writeA = a >= b;
            if (writeA && a == 0) writeA = false;
            if (!writeA && b == 0) writeA = true;
            if (writeA) {
                sb.Append('a');
                a--;
                lastA++;
                lastB = 0;
            } else {
                sb.Append('b');
                b--;
                lastB++;
                lastA = 0;
            }
        }
        return sb.ToString();
    }
}
