Classic DP: `dp[i][j]` = whether `s[0..i)` matches `p[0..j)`. Use a rolling 1D array for efficiency.

```csharp
public class Solution {
    public bool IsMatch(string s, string p) {
        int n = s.Length, m = p.Length;
        bool[] prev = new bool[m + 1];
        bool[] cur = new bool[m + 1];
        prev[0] = true;
        for (int j = 1; j <= m; j++) {
            prev[j] = prev[j - 1] && p[j - 1] == '*';
        }
        for (int i = 1; i <= n; i++) {
            cur[0] = false;
            for (int j = 1; j <= m; j++) {
                char pc = p[j - 1];
                if (pc == '*') {
                    cur[j] = cur[j - 1] || prev[j];
                } else if (pc == '?' || pc == s[i - 1]) {
                    cur[j] = prev[j - 1];
                } else {
                    cur[j] = false;
                }
            }
            bool[] tmp = prev;
            prev = cur;
            cur = tmp;
        }
        return prev[m];
    }
}
```

