Approach: compute in-degrees; each node must have in-degree ≤ 1, exactly one node has in-degree 0 (the root). Then BFS/DFS from the root and verify all n nodes are reached (ensures connectivity and no cycles, since edge count is n-1 and each node has one parent).

```csharp
public class Solution {
    public bool ValidateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) {
                indeg[leftChild[i]]++;
                if (indeg[leftChild[i]] > 1) return false;
            }
            if (rightChild[i] != -1) {
                indeg[rightChild[i]]++;
                if (indeg[rightChild[i]] > 1) return false;
            }
        }
        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;
        bool[] visited = new bool[n];
        var stack = new Stack<int>();
        stack.Push(root);
        visited[root] = true;
        int count = 0;
        while (stack.Count > 0) {
            int cur = stack.Pop();
            count++;
            int l = leftChild[cur], r = rightChild[cur];
            if (l != -1) {
                if (visited[l]) return false;
                visited[l] = true;
                stack.Push(l);
            }
            if (r != -1) {
                if (visited[r]) return false;
                visited[r] = true;
                stack.Push(r);
            }
        }
        return count == n;
    }
}
